\begin{defn}\ollabel{def:equivalenceclass}
Let $R \subseteq A^2$ be an equivalence relation. For each $x \in A$,
the \emph{equivalence class} of $x$ in~$A$ is the set $\equivrep{x}{R}
= \Setabs{y \in A}{Rxy}$. The \emph{quotient} of $A$ under~$R$ is
$\equivclass{A}{R} = \Setabs{\equivrep{x}{R}}{x \in A}$, i.e., the set
of these equivalence classes. 
\end{defn}

target_before.text:
\begin{defn}\ollabel{def:equivalenceclass}
فرض کرو کہ $R \subseteq A^2$ اک ہم ارزیت دا تعلق اے۔ ہر $x \in A$ لئی،
$x$ دا $A$ وچ \emph{ہم ارزیت دا طبقہ} اوہ سیٹ $\equivrep{x}{R}
= \Setabs{y \in A}{Rxy}$ اے۔ سیٹ $A$ دا تعلق $R$ تحت \emph{خارج قسمت سیٹ}
$\equivclass{A}{R} = \Setabs{\equivrep{x}{R}}{x \in A}$ اے، یعنی ایہناں
ہم ارزیت دے طبقیاں دا سیٹ۔
\end{defn}

target_after.text:
\begin{defn}\ollabel{def:equivalenceclass}
فرض کرو کہ $R \subseteq A^2$ اک ہم ارزیت دا تعلق اے۔ ہر $x \in A$ لئی،
$x$ دا $A$ وچ \emph{ہم ارزیت دا طبقہ} اوہ سیٹ $\equivrep{x}{R}
= \Setabs{y \in A}{Rxy}$ اے۔ $A$ دا، $R$ دے تحت، \emph{خارج قسمت سیٹ
(quotient)}، $\equivclass{A}{R} = \Setabs{\equivrep{x}{R}}{x \in A}$،
ایہناں ہم ارزیت دے طبقیاں دا سیٹ اے۔
\end{defn}

