\begin{prop}\ollabel{prop:bijection-inverse}
جے $f\colon A \to B$، !!{bijective} اے، تاں اک
فنکشن~$f^{-1}\colon B \to A$ اے جیہدے لئی ہر $x \in A$ اُتے
$f^{-1}(f(x)) = x$ تے ہر $y \in B$ اُتے $f(f^{-1}(y)) = y$۔
\end{prop}

target_after.text:
\begin{prop}\ollabel{prop:bijection-inverse}
جے $f\colon A \to B$، !!{bijective} (اک بہ اک تے ہر ہدف قدر لین
والا؛ bijective) اے، تاں اک اُلٹ فنکشن (inverse function)
$f^{-1}\colon B \to A$ اے جیہدے لئی ہر $x \in A$ اُتے
$f^{-1}(f(x)) = x$ تے ہر $y \in B$ اُتے $f(f^{-1}(y)) = y$۔
\end{prop}

